let lesson,days=[],view='lesson',part=0,quizIndex=0,currentDay=28,groups=[];
const defaultState={completedDays:[],scores:{},currentDay:28};
let state={...defaultState};
try{const saved=JSON.parse(localStorage.getItem('toeic-studio')||'{}');state={...defaultState,...saved};if(!Array.isArray(state.completedDays))state.completedDays=[];if(saved.done&&!state.completedDays.includes(28))state.completedDays.push(28);if(!state.scores||typeof state.scores!=='object')state.scores={}}catch{}

const day28Groups=[
  {name:'學習概覽',ids:[0]},{name:'30 個核心單字',ids:[1]},
  {name:'文法總複習',ids:[2,3,4,5,6,7]},{name:'聽力階段模考',ids:[8,9,10,11]},
  {name:'雙篇閱讀',ids:[12,13]},{name:'Part 5 仿真題',ids:[14]},
  {name:'階段小考與解析',ids:[15,16]},{name:'錯題回收與作業',ids:[17,18,19,20]}
];
const $=selector=>document.querySelector(selector);
const esc=value=>String(value).replace(/[&<>"']/g,char=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[char]));
const isCompleted=day=>state.completedDays.includes(day);

function save(){state.currentDay=currentDay;try{localStorage.setItem('toeic-studio',JSON.stringify(state))}catch{}updateProgress()}
function updateProgress(){const completed=new Set(state.completedDays).size;$('#progress').innerHTML=`${completed} <small>/ 90 天</small>`;$('#bar').style.width=`${completed*100/90}%`}
function inline(text){return esc(text).replace(/\*\*(.*?)\*\*/g,'<strong>$1</strong>').replace(/`([^`]+)`/g,'<code>$1</code>')}
function md(text){let output='',table=false,list=false;for(const line of String(text||'').split('\n')){if(!line.startsWith('|')&&table){output+='</tbody></table>';table=false}if(!/^[-*] /.test(line)&&list){output+='</ul>';list=false}if(/^\|/.test(line)){if(/^\|[\s:|-]+\|$/.test(line))continue;if(!table){output+='<table><tbody>';table=true}output+='<tr>'+line.split('|').slice(1,-1).map(cell=>'<td>'+inline(cell.trim())+'</td>').join('')+'</tr>';continue}if(/^[-*] /.test(line)){if(!list){output+='<ul>';list=true}output+='<li>'+inline(line.slice(2))+'</li>';continue}if(/^#{1,4} /.test(line))output+='<h3>'+inline(line.replace(/^#+ /,''))+'</h3>';else if(line.startsWith('>'))output+='<blockquote>'+inline(line.slice(1).trim())+'</blockquote>';else if(line==='---')output+='<hr>';else if(line.trim())output+='<p>'+inline(line)+'</p>'}return output+(table?'</tbody></table>':'')+(list?'</ul>':'')}
function makeGroups(){if(lesson.day===28&&lesson.sections.length>=21)return day28Groups;return lesson.sections.map((section,index)=>({name:section.title.replace(/^[①②③④⑤⑥⑦⑧⑨⑩⑪⑫⑬⑭⑮⑯⑰⑱⑲⑳]\s*/,''),ids:[index]}))}
function navigate(nextView){if('speechSynthesis'in window)speechSynthesis.cancel();view=nextView;document.querySelectorAll('.nav').forEach(button=>button.classList.toggle('active',button.dataset.view===view));render()}

function updateLessonHeader(){const completed=isCompleted(currentDay);const vocabularyCount=lesson.vocabulary?.length||0;const questionCount=lesson.quizzes?.reduce((sum,quiz)=>sum+quiz.questions.length,0)||0;const minuteText=lesson.durationMinutes?.max?`${lesson.durationMinutes.min}–${lesson.durationMinutes.max}`:lesson.minutes;$('.page-top .eyebrow').textContent=`DAY ${String(currentDay).padStart(2,'0')} · TOEIC TRAINING`;$('.day-badge strong').textContent=currentDay;$('.stats > div:nth-child(2) strong').innerHTML=`${esc(minuteText)} <small>分鐘</small>`;$('.stats > div:nth-child(3) strong').textContent=lesson.level||'依教材';$('.lesson-intro').innerHTML=`<div class="eyebrow">DAY ${currentDay} LESSON</div><h2>${esc(lesson.title)}</h2><p>${esc(lesson.source||lesson.courseTitle||'TOEIC 金色證書 90 天訓練')}</p><span class="pill">${lesson.sections.length} 個章節</span><span class="pill">${vocabularyCount} 個單字</span><span class="pill">${questionCount} 題練習</span>${completed?'<span class="pill">✓ 已完成</span>':''}`}
function renderSection(section,index,showTitle=true){const canSpeak=/listening|聽力/i.test(section.title)&&/聽力稿：/.test(section.markdown);const controls=canSpeak?`<div class="listen"><button class="secondary" data-speak="${index}">▶ 朗讀聽力稿</button><button class="secondary" data-stop>停止</button></div>`:'';const title=showTitle?`<h3>${esc(section.title)}</h3>`:'';return `<section>${title}${controls}${md(section.markdown)}</section>`}
function renderLesson(){const group=groups[part];const completeLabel=isCompleted(currentDay)?'已完成今日學習':'完成今日學習';const sourceLink=lesson.sourceUrl?`<br><a href="${esc(lesson.sourceUrl)}" target="_blank" rel="noopener">原始課程連結</a>`:'';const showSectionTitles=lesson.day===28||group.ids.length>1;return `<div class="lesson-layout"><div><section class="card lesson-intro"></section><article class="card"><div class="section-head"><h2>${esc(group.name)}</h2><span class="muted">${part+1} / ${groups.length}</span></div><div class="read-area">${group.ids.map(index=>renderSection(lesson.sections[index],index,showSectionTitles)).join('')}</div><div class="section-head" style="margin-top:25px"><button class="secondary" id="previous" ${part===0?'disabled':''}>上一節</button><button class="primary" id="next">${part===groups.length-1?completeLabel:'下一節'}</button></div></article></div><div><nav class="card toc" aria-label="教材章節"><h3>Day ${currentDay} 學習路線</h3>${groups.map((item,index)=>`<button data-part="${index}" class="${index===part?'active':''}">${String(index+1).padStart(2,'0')}　${esc(item.name)}</button>`).join('')}</nav><div class="notice">Day ${currentDay} 教材已完整匯入。${sourceLink}</div></div></div>`}
function renderCalendar(){const availableCount=days.filter(day=>day.available).length;return `<div class="card"><div class="section-head"><h2>課程目錄</h2><span class="muted">${availableCount} / 90 天已匯入</span></div><div class="calendar">${days.map(day=>`<button class="day ${day.available?'available':''}" ${day.available?`data-open-day="${day.day}"`:'disabled'} aria-label="Day ${day.day} ${esc(day.title)}"><span>DAY</span><b>${day.day}</b><span>${day.available?(isCompleted(day.day)?'已完成':'開始學習'):'待匯入'}</span></button>`).join('')}</div></div>`}
function renderWords(){if(!lesson.vocabulary?.length)return '<div class="card">本日沒有單字資料。</div>';return `<div class="words">${lesson.vocabulary.map((word,index)=>`<button class="card word" data-word="${index}" aria-label="朗讀 ${esc(word.word)}"><strong>${esc(word.word)} <small style="display:inline">♫</small></strong><small>${esc(word.partOfSpeech||'')} ${esc(word.meaning)}</small><span>${esc(word.phrase||'')}</span></button>`).join('')}</div><p class="muted">點選單字卡聆聽發音。語音取決於瀏覽器支援。</p>`}
function getSavedScore(){return state.scores[currentDay]?.[quizIndex]}
function renderQuiz(){if(!lesson.quizzes?.length)return '<div class="card">本日沒有測驗資料。</div>';if(!lesson.quizzes[quizIndex])quizIndex=0;const quiz=lesson.quizzes[quizIndex],savedScore=getSavedScore();return `<div class="listen">${lesson.quizzes.map((item,index)=>`<button class="${index===quizIndex?'primary':'secondary'}" data-quiz="${index}">${esc(item.title)} · ${item.questions.length} 題</button>`).join('')}</div><div class="notice">提交後會顯示正解與解析。${savedScore!=null?` 上次成績：${savedScore} / ${quiz.questions.length}`:''}</div><form id="quiz-form" class="card">${quiz.questions.map((question,index)=>`<section class="quiz-q" id="question-${question.id}"><h3><span class="muted">${String(index+1).padStart(2,'0')} / ${quiz.questions.length}</span><br>${inline(question.prompt)}</h3>${Object.entries(question.options).map(([key,value])=>`<label class="option"><input required type="radio" name="q${question.id}" value="${key}"><span>${key}. ${inline(value)}</span></label>`).join('')}<div class="feedback"></div></section>`).join('')}<div class="score" id="result" role="status"></div><button class="primary" type="submit">提交答案</button> <button class="secondary" type="button" id="retry">重新作答</button></form>`}

function render(){if(!lesson)return;const titles={lesson:[lesson.title,lesson.courseTitle||lesson.source||`Day ${currentDay} 每日教材`],calendar:['你的 90 天學習旅程','選擇已匯入的日期，開始或繼續學習。'],words:[`Day ${currentDay} 核心單字`,`${lesson.vocabulary?.length||0} 個單字，搭配一起記更牢。`],quiz:[`Day ${currentDay} 階段練習`,'完成作答後提交，立即查看答案與解析。']};$('#page-title').textContent=titles[view][0];$('#page-sub').textContent=titles[view][1];if(view==='lesson')$('#content').innerHTML=renderLesson();else if(view==='calendar')$('#content').innerHTML=renderCalendar();else if(view==='words')$('#content').innerHTML=renderWords();else $('#content').innerHTML=renderQuiz();if(view==='lesson')updateLessonHeader();bind()}
function speak(text){if(!('speechSynthesis'in window)){alert('此瀏覽器不支援語音朗讀。');return}speechSynthesis.cancel();const utterance=new SpeechSynthesisUtterance(text);utterance.lang='en-US';utterance.rate=.88;speechSynthesis.speak(utterance)}
async function loadDay(day,nextView='lesson'){$('#content').innerHTML='<div class="card">正在載入教材…</div>';try{const response=await fetch(`data/day-${day}.json`);if(!response.ok)throw new Error(`HTTP ${response.status}`);lesson=await response.json();currentDay=day;part=0;quizIndex=0;groups=makeGroups();save();navigate(nextView)}catch{$('#content').innerHTML=`<div class="card">Day ${day} 教材載入失敗，請稍後再試。</div>`}}

function bind(){document.querySelectorAll('[data-part]').forEach(button=>button.onclick=()=>{part=Number(button.dataset.part);render()});$('#previous')?.addEventListener('click',()=>{part--;render()});$('#next')?.addEventListener('click',()=>{if(part<groups.length-1)part++;else if(!isCompleted(currentDay)){state.completedDays.push(currentDay);save()}render();window.scrollTo({top:240,behavior:'smooth'})});document.querySelectorAll('[data-open-day]').forEach(button=>button.onclick=()=>loadDay(Number(button.dataset.openDay)));document.querySelectorAll('[data-word]').forEach(button=>button.onclick=()=>speak(lesson.vocabulary[Number(button.dataset.word)].word));document.querySelectorAll('[data-speak]').forEach(button=>button.onclick=()=>{const markdown=lesson.sections[Number(button.dataset.speak)].markdown;const script=markdown.split('聽力稿：')[1]?.split('答案：')[0]||markdown;speak(script.replace(/^>\s?/gm,'').trim())});document.querySelectorAll('[data-stop]').forEach(button=>button.onclick=()=>speechSynthesis.cancel());document.querySelectorAll('[data-quiz]').forEach(button=>button.onclick=()=>{quizIndex=Number(button.dataset.quiz);render()});$('#retry')?.addEventListener('click',render);$('#quiz-form')?.addEventListener('submit',event=>{event.preventDefault();const quiz=lesson.quizzes[quizIndex],formData=new FormData(event.target);let score=0;quiz.questions.forEach(question=>{const answer=formData.get('q'+question.id),correct=answer===question.answer;if(correct)score++;const explanation=question.explanation?`<br>${inline(question.explanation)}`:'';$(`#question-${question.id} .feedback`).innerHTML=`<p class="${correct?'correct':'wrong'}">${correct?'✓ 答對了':`答錯了 · 你的答案 ${esc(answer)}`} · 正確答案 ${question.answer}：${inline(question.options[question.answer])}${explanation}</p>`});if(!state.scores[currentDay])state.scores[currentDay]={};state.scores[currentDay][quizIndex]=score;save();const percentage=score/quiz.questions.length;$('#result').textContent=`${score} / ${quiz.questions.length} · ${percentage>=.9?'掌握得很好！':percentage>=.75?'再複習幾個觀念就更穩了。':'回到教材，釐清錯題的判斷依據。'}`;$('#result').scrollIntoView({behavior:'smooth',block:'center'})})}

document.querySelectorAll('[data-view]').forEach(button=>button.onclick=()=>navigate(button.dataset.view));
async function start(){try{const response=await fetch('data/curriculum.json');if(!response.ok)throw new Error(`HTTP ${response.status}`);days=await response.json();const availableDays=days.filter(day=>day.available).map(day=>day.day);const preferredDay=availableDays.includes(Number(state.currentDay))?Number(state.currentDay):availableDays[0];await loadDay(preferredDay||28)}catch{$('#content').innerHTML='<div class="card">課程目錄載入失敗，請重新整理頁面再試一次。</div>'}}
start();
